from attrs import define, field


def create_test_state_dict(data):
    raw_test_states = data.split("\n\n")
    test_states = map(TestState.from_string, raw_test_states)
    return {state.suite: state for state in test_states}


@define
class TestState:
    __test__ = False
    suite = field()
    state = field()
    case_index = field(converter=int)
    elapsed_time = field(converter=int)
    remaining_time = field(converter=int)
    executed_cases = field(converter=int)
    remaining_cases = field(converter=int)
    passed_cases = field(converter=int)
    failed_cases = field(converter=int)
    passed_snmp_cases = field(converter=int)
    failed_snmp_cases = field(converter=int)
    failed_snmp_traps = field(converter=int)
    passed_safeguard_checks = field(converter=int)
    warning_safeguard_checks = field(converter=int)
    failed_safeguard_checks = field(converter=int)
    failed_isa_secure_cases = field(converter=int)
    failed_syslog_messages = field(converter=int)
    other_cases = field(converter=int)
    total_cases = field(converter=int)
    case_rate_per_second = field(converter=float)

    @classmethod
    def from_string(cls, data):
        def split_by_colon(row):
            return row.split(":")

        def split_by_newline(s):
            return s.split("\n")

        def replaced(key):
            return key.replace("-", "_")

        attributes = {replaced(key): value for key, value in map(split_by_colon, split_by_newline(data))}

        return cls(**attributes)
